def gen(rng):
    def fmt(a, ops):
        lines = [str(len(a)), ' '.join(map(str, a)), str(len(ops))]
        for o in ops:
            lines.append(' '.join(map(str, o)))
        return '\n'.join(lines)

    def rand_ops(n, q, vmax, wide=False):
        ops = []
        for _ in range(q):
            if rng.random() < 0.5:
                ops.append((1, rng.randint(1, n), rng.randint(-vmax, vmax)))
            else:
                if wide:
                    l = rng.randint(1, max(1, n // 10))
                    r = rng.randint(n - n // 10, n)
                else:
                    l = rng.randint(1, n)
                    r = rng.randint(l, n)
                ops.append((2, l, r))
        return ops

    tests = [fmt([7], [(2, 1, 1), (1, 1, -10), (2, 1, 1)]),
             fmt([0], [(2, 1, 1)]),
             fmt([5, 5], [(1, 1, 1), (1, 2, -1)]),
             fmt([1, 2, 3, 4], [(2, 1, 4), (2, 2, 3), (2, 4, 4), (1, 4, 10), (2, 1, 4), (2, 4, 4)]),
             fmt([10 ** 4] * 8, [(2, 1, 8), (1, 8, -10 ** 4), (2, 1, 8), (2, 8, 8)])]
    for n in (2, 3, 5, 8, 12, 16, 20):
        for _ in range(2):
            a = [rng.randint(-10, 10) for _ in range(n)]
            tests.append(fmt(a, rand_ops(n, rng.randint(3, 12), 10)))
    n = 100000
    a = [rng.randint(-10 ** 4, 10 ** 4) for _ in range(n)]
    tests.append(fmt(a, rand_ops(n, 100000, 10 ** 4, True)))
    tests.append(fmt(a, [(2, rng.randint(1, 5), rng.randint(n - 5, n)) for _ in range(100000)]))
    a = [rng.randint(-10 ** 4, 10 ** 4) for _ in range(n)]
    ops = []
    for i in range(100000):
        if i % 4 == 0:
            ops.append((1, rng.randint(1, n), rng.randint(-10 ** 4, 10 ** 4)))
        else:
            ops.append((2, 1, rng.randint(n // 2, n)))
    tests.append(fmt(a, ops))
    return tests

